parameters.inputSchema:
{
  "name": "email_classification",
  "description": "Classifies incoming customer emails to determine if they require a support response.",
  "strict": true,
  "schema": {
    "type": "object",
    "properties": {
      "classification": {
        "type": "string",
        "description": "Classify as RESPOND if the sender is asking for help, information, or action related to orders or customer service. Classify as DO_NOT_RESPOND if the email is promotional, spam, or unrelated to customer support.",
        "enum": [
          "RESPOND",
          "DO_NOT_RESPOND"
        ]
      }
    },
    "required": [
      "classification"
    ],
    "additionalProperties": false
  }
}

{
  "type": "object",
  "properties": {
    "subject": {
      "type": "string",
      "description": "A clear, professional, and concise subject line for the email response."
    },
    "email_body": {
      "type": "string",
      "description": "The main text of the email. Must be conversational, professional, plain-text (no Markdown) and end exactly with 'Best Regards,\nCustomer Support Team'."
    }
  },
  "required": [
    "subject",
    "email_body"
  ]
}
